import rego.v1

default allow := false

allow if {
    not supplier_blocked_for_purchase_order
}

supplier_blocked_for_purchase_order if {
    input.trusted.supplierOnHold == true
    hold_type_blocks_purchase_orders
}

hold_type_blocks_purchase_orders if {
    input.trusted.holdType == "Invoices"
}

hold_type_blocks_purchase_orders if {
    input.trusted.holdType == "All"
}
